// notes: worked MCP server example, generated by `prodforge init mcp-server notes`
// and extended with real tools: ping plus an in-memory notes store.
// Everything exported here is pure and unit-testable without the SDK;
// the MCP server itself is started by main() via dynamic SDK imports.
export interface Note {
  id: number;
  title: string;
  body: string;
}

export class NotesStore {
  private notes: Note[] = [];
  private nextId = 1;

  list(): Note[] {
    return [...this.notes];
  }

  add(title: unknown, body: unknown): Note {
    if (typeof title !== "string" || title.trim().length === 0) {
      throw new Error("title must be a non-empty string");
    }
    if (typeof body !== "string") {
      throw new Error("body must be a string");
    }
    const note: Note = { id: this.nextId, title: title.trim(), body };
    this.nextId += 1;
    this.notes.push(note);
    return note;
  }

  get(id: unknown): Note {
    if (typeof id !== "number" || !Number.isInteger(id)) {
      throw new Error("id must be an integer");
    }
    const note = this.notes.find((n) => n.id === id);
    if (!note) {
      throw new Error(`no note with id ${id}`);
    }
    return note;
  }
}

const defaultStore = new NotesStore();

export const TOOLS = [
  { name: "ping", description: "Health check tool. Returns pong." },
  { name: "add_note", description: "Add a note. Args: title (string), body (string). Returns the note as JSON." },
  { name: "list_notes", description: "List all notes as JSON." },
  { name: "get_note", description: "Get one note by id. Args: id (number). Returns the note as JSON." },
] as const;

export function handleTool(toolName: string, args: Record<string, unknown> = {}, store: NotesStore = defaultStore): string {
  if (toolName === "ping") return "pong";
  if (toolName === "add_note") return JSON.stringify(store.add(args.title, args.body));
  if (toolName === "list_notes") return JSON.stringify(store.list());
  if (toolName === "get_note") return JSON.stringify(store.get(args.id));
  throw new Error(`unknown tool: ${toolName}`);
}

export function toolNames(): string[] {
  return TOOLS.map((t) => t.name);
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  if (args[0] === "ping") {
    console.log(handleTool("ping"));
    return;
  }
  // MCP stdio server: loaded only when actually serving, never at import time.
  const { McpServer } = await import("@modelcontextprotocol/sdk/server/mcp.js");
  const { StdioServerTransport } = await import("@modelcontextprotocol/sdk/server/stdio.js");
  const { z } = await import("zod");
  const server = new McpServer({ name: "notes", version: "0.1.0" });
  const store = defaultStore;
  server.tool("ping", "Health check tool. Returns pong.", {}, async () => ({
    content: [{ type: "text", text: handleTool("ping") }],
  }));
  server.tool("add_note", "Add a note.", { title: z.string(), body: z.string() }, async ({ title, body }) => ({
    content: [{ type: "text", text: handleTool("add_note", { title, body }, store) }],
  }));
  server.tool("list_notes", "List all notes.", {}, async () => ({
    content: [{ type: "text", text: handleTool("list_notes", {}, store) }],
  }));
  server.tool("get_note", "Get one note by id.", { id: z.number() }, async ({ id }) => ({
    content: [{ type: "text", text: handleTool("get_note", { id }, store) }],
  }));
  await server.connect(new StdioServerTransport());
}

const isMain = process.argv[1] !== undefined && import.meta.url.endsWith(process.argv[1].split("/").pop() ?? "");
if (isMain) main().catch((err) => { console.error(err); process.exit(1); });
